const state = getWorkflowStaticData('global');
const now = new Date();

// Säker lookback: körning var 10:e minut men läs normalt 12 minuter bakåt (2 min buffert)
const requestedLookback = Number($env.LOOKBACK_MINUTES || 12);
const clampedLookback = Math.min(Math.max(requestedLookback, 5), 30); // aldrig längre än 30 min

const fallbackSince = new Date(now.getTime() - clampedLookback * 60 * 1000);
let since = state.lastPollAt ? new Date(state.lastPollAt) : fallbackSince;

// Cap så att den inte kollar för långt bak vid stopp/omstart
const maxSince = new Date(now.getTime() - 30 * 60 * 1000);
if (since < maxSince || Number.isNaN(since.getTime())) {
  since = maxSince;
}

state.lastPollAt = now.toISOString();

return [{ json: {
  since: since.toISOString(),
  until: now.toISOString(),
  lookbackMinutesUsed: Math.round((now.getTime() - since.getTime()) / 60000),
  inboxFolderId: $env.OUTLOOK_INBOX_FOLDER_ID || 'inbox',
  sentFolderId: $env.OUTLOOK_SENT_FOLDER_ID || 'sentitems'
}}];

const rows = [];

const extractCompany = (email) => {
  const domain = (email || '').split('@')[1] || '';
  return domain.replace(/^www\./i, '').toLowerCase();
};

const extractOrderNumber = (text) => {
  const m = (text || '').match(/ 819\d{3} /); // 6 siffror som börjar med 819
  return m ? m[0] : null;
};

const extractQuestionText = (subject, body) => {
  const source = `${subject || ''} ${body || ''}`.replace(/\s+/g, ' ').trim();
  const q = source.match(/([^?.!]{3,250}\?)/);
  return q ? q[1].trim() : source.slice(0, 300);
};

for (const item of items) {
  const m = item.json;
  const subject = (m.subject || '').trim();
  const bodyPreview = (m.bodyPreview || '').toString();
  const body = ((m.bodyPreview || '') + ' ' + (m.body?.content || '')).toLowerCase();
  const toList = (m.toRecipients || []).map(r => r?.emailAddress?.address).filter(Boolean);
  const to = toList.join('; ');
  const from = m.from?.emailAddress?.address || '';

  const isAuto = /(noreply|do-not-reply|mailer-daemon|out of office|automatiskt svar)/i.test(subject + ' ' + from);
  if (isAuto) continue;

  const hasQuestion = /[?]|kan du|kan ni|återkoppla|behöver|när kan|vill du|vill ni/i.test(subject + ' ' + body);
  if (!hasQuestion) continue;

  const isFortnox = /(fortnox|offert|quote)/i.test(subject + ' ' + body);
  const orderNumber = extractOrderNumber(`${subject} ${bodyPreview}`);
  const questionText = extractQuestionText(subject, bodyPreview);

  rows.push({json:{
    external_message_id: m.id || '',
    conversation_id: m.conversationId || '',
    direction: 'outgoing',
    case_type: isFortnox ? 'fortnox_offert' : 'question_out',
    status: 'waiting_customer',
    customer_email: to,
    customer_company: extractCompany(toList[0] || ''),
    owner_email: from,
    waiting_for_email: toList[0] || to,
    waiting_for_company: extractCompany(toList[0] || ''),
    subject,
    question_text: questionText,
    question_excerpt: bodyPreview.slice(0,600),
    order_number: orderNumber,
    sent_at: m.sentDateTime || null,
    received_at: null,
    asked_at: m.sentDateTime || null,
    answered_at: null,
    source_system: 'office365_graph'
  }});
}
return rows;

