const state = getWorkflowStaticData('global');
state.lastLunchSummaryDate = state.lastLunchSummaryDate || '';
const now = new Date();
const today = now.toISOString().slice(0,10);
const should = now.getHours() === 12 && state.lastLunchSummaryDate !== today;
if (should) state.lastLunchSummaryDate = today;
return [{json:{shouldSendLunch: should}}];

const rows = items.map(i => i.json);
const waitingCustomer = rows.filter(r => r.status === 'waiting_customer');
const waitingMe = rows.filter(r => r.status === 'waiting_me');
const lines = [];
lines.push(`Lunchrapport ${new Date().toISOString().slice(0,10)}`);
lines.push('');
lines.push('Jag väntar på svar från kund:');
if (!waitingCustomer.length) lines.push('- Inga öppna ärenden.');
for (const r of waitingCustomer) {
  lines.push(`- ${r.waiting_for_email || r.customer_email || '(okänd)'} (${r.waiting_for_company || r.customer_company || 'okänt bolag'}) | ${r.subject || '(utan ämne)'} | order: ${r.order_number || '-'} | typ: ${r.case_type}`);
}
lines.push('');
lines.push('Kunder väntar på svar från mig:');
if (!waitingMe.length) lines.push('- Inga öppna ärenden.');
for (const r of waitingMe) {
  lines.push(`- ${r.customer_email || '(okänd)'} (${r.customer_company || 'okänt bolag'}) | ${r.subject || '(utan ämne)'} | order: ${r.order_number || '-'} | typ: ${r.case_type}`);
}
return [{json:{body: lines.join('\n')}}];
